// Vanilla buildings usable in villages, measured from the Workbench (profile/MapGen/prefabs.txt:
// local bounds of each prefab, metres). Generated by a one-off filter on the file names:
// ruins, interiors, parts, "_base", furniture and damaged variants are left out.
// No church or town hall exists in the vanilla set: the village pub is the unique "civic" building.

export type BuildingCat = 'houseS' | 'houseM' | 'houseL' | 'farm' | 'annex' | 'shed' | 'civic'

export interface Building {
  prefab: string // "{GUID}path.et"
  cat: BuildingCat
  minX: number
  minZ: number
  maxX: number
  maxZ: number
  tpl?: string // captured parcel laid down with it (templates.ts)
}

//! Door side is unknown. Convention: the street front of a building is its local +Z side (the
//! model's forward axis), so yaw = atan2(towardsRoadX, towardsRoadZ). If in-game the backs face the
//! road, set this to 180 (90 / -90 if the doors are on a long side) — like EMBANK_YAW in water.ts.
export const FRONT_YAW = 0

